'use strict';
let journeyStarted=false,guideClosed=false,guideTipIndex=0,guideStep=-1,missionFeedback=null;
const journeyStages=[
 {title:'Tu misión',verb:'Elegí tu objetivo',text:'¿Explorar con luz o enviar noticias a casa?',pose:'green',kind:'rover'},
 {title:'El lugar',verb:'Explorá el terreno',text:'Mirá la Luna en colores y compará sitios.',pose:'terrain',kind:'terrain'},
 {title:'La fecha',verb:'Mové el tiempo',text:'Descubrí cómo cambia el cielo durante tu misión.',pose:'terrain',kind:'time'},
 {title:'La energía',verb:'Cuidá tu batería',text:'Orientá el panel y preparate para la sombra.',pose:'energy',kind:'energy'},
 {title:'La conexión',verb:'Buscá la Tierra',text:'Evitá obstáculos o guardá datos para después.',pose:'comms',kind:'comms'},
 {title:'Tu plan',verb:'Uní las decisiones',text:'Revisá tu misión y probá otras combinaciones.',pose:'green',kind:'plan'}
];
function journeyArt(kind){const defs='<defs><linearGradient id="journeyGround" x2="0" y2="1"><stop stop-color="#436375"/><stop offset="1" stop-color="#15283d"/></linearGradient></defs>';let drawing='';
 if(kind==='terrain')drawing='<path d="M0 100L35 65 70 83 115 25 157 77 200 44 240 100V130H0Z" fill="#4c6772"/><path d="M12 110L52 91 78 105 122 79 163 103 212 81" fill="none" stroke="#8ce4a1" stroke-width="12" stroke-linecap="round"/><circle cx="122" cy="79" r="7" fill="#eaffc5"/>';
 else if(kind==='time')drawing='<circle cx="120" cy="66" r="46" fill="#203e57" stroke="#6ccbd4" stroke-width="2"/><path d="M120 35V66L148 80" fill="none" stroke="#deeff1" stroke-width="5" stroke-linecap="round"/><circle cx="47" cy="54" r="17" fill="#f9c65c"/><path d="M192 32a25 25 0 1 0 17 42 26 26 0 0 1-17-42" fill="#a9bad7"/>';
 else if(kind==='energy')drawing='<circle cx="42" cy="35" r="20" fill="#f9c65c"/><path d="M55 50L83 70" stroke="#f9c65c" stroke-width="3" stroke-dasharray="5 5"/><path d="M75 94L93 45H151L134 94Z" fill="#2477b2" stroke="#9fdcf3" stroke-width="2"/><path d="M86 67H143M100 45L82 94M123 45L106 94M141 45L125 94" stroke="#a8d9ee"/><rect x="169" y="57" width="47" height="47" rx="9" fill="#365448" stroke="#8ae2a4" stroke-width="2"/><rect x="181" y="47" width="21" height="10" rx="3" fill="#8ae2a4"/><path d="M197 65L185 82H199L188 96" fill="none" stroke="#baf284" stroke-width="4"/>';
 else if(kind==='comms')drawing='<circle cx="190" cy="37" r="25" fill="#369acc"/><path d="M176 18L193 22 188 34 204 40 192 55 178 44" fill="#a4dcad"/><path d="M65 105L83 63 101 105M73 87H94" fill="none" stroke="#cbdde4" stroke-width="5"/><path d="M94 64L167 44" fill="none" stroke="#5cdecd" stroke-width="3" stroke-dasharray="6 5"/><path d="M0 112L125 110 150 76 178 113H240V130H0Z" fill="#253b50"/>';
 else if(kind==='plan')drawing='<rect x="64" y="15" width="113" height="106" rx="12" fill="#24445a" stroke="#8bbcca" stroke-width="2"/><rect x="98" y="10" width="44" height="14" rx="5" fill="#76cfbc"/><path d="M80 47L86 53 98 40M80 73L86 79 98 66M80 99L86 105 98 92" fill="none" stroke="#9ee8a0" stroke-width="4"/><path d="M110 47H157M110 73H157M110 99H147" stroke="#bed7df" stroke-width="4"/>';
 else drawing='<path d="M0 115Q70 89 120 111T240 108V130H0Z" fill="#354e61"/><g transform="translate(69 50)"><path d="M0 39L14 13H74L90 39Z" fill="#78c6d0"/><circle cx="20" cy="47" r="12" fill="#152435" stroke="#a8d4dd" stroke-width="3"/><circle cx="72" cy="47" r="12" fill="#152435" stroke="#a8d4dd" stroke-width="3"/><path d="M44 13V-16L63 -25" stroke="#b3dce4" stroke-width="4"/><circle cx="66" cy="-26" r="5" fill="#f4cb70"/></g><circle cx="204" cy="22" r="14" fill="#f8cd62"/>';
 return `<svg viewBox="0 0 240 130" aria-hidden="true">${defs}${drawing}</svg>`;
}
function renderJourney(){const step=Math.min(mission.step,5),intro=!journeyStarted;const cards=journeyStages.map((s,i)=>`<button class="journey-card ${i===step?'current':''} ${i<step?'complete':''}" data-journey="${i}" aria-label="${i+1}. ${s.title}: ${s.verb}${intro&&i===0?'. Empezar por aquí':''}">${journeyArt(s.kind)}<span class="journey-number">${i<step?'✓':String(i+1).padStart(2,'0')}</span><h3>${s.title}</h3><b>${s.verb}</b><p>${s.text}</p><span class="journey-card-action">${intro&&i===0?'Empezar por aquí →':!intro&&i<=step?'Abrir decisión →':'Ver qué vamos a descubrir ↗'}</span></button>`).join('');$('gameProgress').innerHTML=intro?`<div class="journey-heading"><span class="eyebrow">TU AVENTURA EN SEIS DECISIONES</span><h1>Una misión se construye paso a paso.</h1><p>Conocé el recorrido. Cuando estés listo, tocá <b>Tu misión</b> para empezar con Félicette.</p></div><div class="journey-grid">${cards}</div>`:`<details class="journey-details"><summary><span>DECISIÓN ${step+1} DE 6 · ${journeyStages[step].title}</span><b>Ver el recorrido completo ⌄</b></summary><div class="journey-grid">${cards}</div></details>`;$('gameProgress').classList.add('journey-progress');document.querySelectorAll('[data-journey]').forEach(b=>b.onclick=()=>{const i=+b.dataset.journey;if((!journeyStarted&&i===0)||(journeyStarted&&i<=step)){journeyStarted=true;mission.step=i;missionFeedback=null;guideTipIndex=0;renderMission();$('gameStageTitle')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}else{guideClosed=false;setGuideBubble(journeyStages[i].pose,journeyStages[i].verb,journeyStages[i].text+' '+(!journeyStarted?'Primero abrí «Tu misión».':'Seguí con la decisión actual y llegaremos a esta etapa.'));}});}
function guideDeck(){const a=missionAnalysis();if(!journeyStarted)return ['¡Hola! Soy Félicette.','Antes de despegar, mirá las seis decisiones. Tocá la primera tarjeta y preparemos tu rover.','El verde del mapa de pendientes indica menor inclinación a esa escala; la altitud es otra variable.'];
 const details=[
 ['¡Empecemos por tu objetivo!','Primero elegí tu prioridad: luz para explorar o ventanas para comunicar. La elección cambia cómo vamos a evaluar los siguientes pasos.','No hay un único lugar ideal: una misión puede priorizar luz y otra, comunicación.'],
 ['¿Dónde apoyamos las ruedas?','Las montañas pueden ocultar el Sol o la Tierra. Compará los tres sitios según tu prioridad y después explorá el terreno.','Una zona verde cumple el límite de pendiente del mapa. Todavía hay que revisar rocas, rugosidad y errores del terreno.'],
 ['¡Mové el tiempo!', 'Compará la misma ubicación en otra semana: el relieve no cambia, pero las direcciones del Sol y la Tierra sí.','Un ciclo solar lunar dura unos 29,5 días terrestres. En el polo, las montañas hacen que día y noche no se repartan en mitades fijas.'],
 ['Cuidemos cada watt-hora.','El panel genera electricidad; la batería guarda el excedente para las horas sin generación. Elegí capacidad y orientación y veremos si alcanza.', 'Wh mide energía almacenada; W mide potencia. Una batería de 120 Wh a 8 W dura 15 horas ideales sin recarga.'],
 ['¿Tenemos camino hacia la Tierra?','Para enviar datos hace falta un camino despejado hacia la Tierra. Elegí altura y decidí si necesitás tiempo real o podés esperar una ventana.', 'Una batería más grande no despeja una montaña. Visibilidad geométrica tampoco garantiza una estación o un enlace de radio.'],
 ['Tu plan conecta todas las decisiones.',a&&a.budget.unservedWh>.01?'El balance muestra un déficit. Volvé a energía y compará otra batería o la orientación del panel.':'Revisá lugar, fecha, energía y comunicación. Podés volver a cualquier decisión que ya completaste.','El plan es educativo: faltan validación de terreno, radio y supervivencia térmica para una misión real.'],
 ['¡Aprendizaje completado!','Descargá tu plan o abrí el laboratorio. Comparar otra configuración es una buena forma de seguir investigando.','Tus decisiones tienen consecuencias distintas: no existe una combinación universalmente ideal.']
 ];return details[mission.step];}
function setGuideBubble(pose,title,text){const root=$('felicetteFloating');root.hidden=!document.body.classList.contains('audience-public')||$('publicMission').hidden;root.classList.toggle('bubble-closed',guideClosed);root.querySelector('img').src=`assets/felicette-${pose}.png`;$('floatingGuideTitle').textContent=title;$('floatingGuideText').textContent=text;$('toggleGuide').setAttribute('aria-expanded',String(!guideClosed));$('toggleGuide').setAttribute('aria-label',guideClosed?'Abrir consejo de Félicette':'Ocultar consejo de Félicette');}
function updateFloatingGuide(){if(guideStep!==mission.step){guideStep=mission.step;guideTipIndex=0;guideClosed=false;}const deck=guideDeck(),pose=journeyStages[Math.min(mission.step,5)].pose;setGuideBubble(pose,missionFeedback&&guideTipIndex===0?missionFeedback.title:deck[0],missionFeedback&&guideTipIndex===0?missionFeedback.reason:deck[1+guideTipIndex%(deck.length-1)]);}
document.body.insertAdjacentHTML('beforeend',`<aside id="felicetteFloating" class="felicette-floating" aria-label="Consejos de Félicette" hidden><div class="felicette-bubble"><span class="comic-kicker">FÉLICETTE DICE…</span><button id="closeGuide" aria-label="Minimizar consejo">×</button><h2 id="floatingGuideTitle"></h2><p id="floatingGuideText" aria-live="polite"></p><button id="nextGuideTip">Otro dato ✦</button></div><button id="toggleGuide" class="felicette-avatar" aria-controls="floatingGuideText" aria-expanded="true"><img src="assets/felicette-green.png" alt="Félicette flotando, gata alienígena verde y blanca"><span>Tu copilota ✦</span></button></aside>`);
$('closeGuide').onclick=()=>{guideClosed=true;updateFloatingGuide();};$('toggleGuide').onclick=()=>{guideClosed=!guideClosed;updateFloatingGuide();};$('nextGuideTip').onclick=()=>{guideTipIndex++;updateFloatingGuide();};
window.addEventListener('lunar-science-sample',e=>{if(!$('publicMission').hidden){const r=e.detail.row;const area=$('sciencePublic');if(area&&area.getBoundingClientRect().top<innerHeight&&area.getBoundingClientRect().bottom>0){guideClosed=false;setGuideBubble('comms','Leamos este caso NASA.',`Sol: ${r.sun.status==='clear_within_sampled_radius'?'supera el horizonte analizado':'sin despeje confirmado'}. Tierra: ${r.earth.status==='clear_within_sampled_radius'?'supera el horizonte analizado':'sin despeje confirmado'}. Tocá Sol o Tierra para ver la dirección y la montaña en el esquema.`);}}});
function gameEnergyFlow(a){const pct=Math.max(0,Math.min(100,a.budget.finalStoredWh/mission.capacity*100));return `<section class="energy-story"><div><span class="eyebrow">SEGUÍ EL CAMINO DE LA ENERGÍA</span><h2>Del Sol a las ruedas.</h2><p>Durante siete días, el panel genera, el rover consume y la batería guarda el excedente que puede aceptar.</p></div><div class="energy-flow"><article>${journeyArt('energy')}<b>Panel solar</b><span>${Math.round(a.budget.generatedWh).toLocaleString('es-AR')} Wh generados</span></article><i aria-hidden="true">→</i><article><div class="battery-illustration"><div style="height:${pct}%"></div><b>${Math.round(pct)} %</b></div><b>Batería al terminar</b><span>${Math.round(a.budget.finalStoredWh)} de ${mission.capacity} Wh</span></article><i aria-hidden="true">→</i><article>${journeyArt('rover')}<b>Tu rover</b><span>Consume ${mission.load} W constantes</span></article></div><p class="game-small">Balance simplificado del período, no flujo instantáneo. La capacidad limita lo que se guarda; la generación no equivale a carga almacenada.</p></section>`;}
function assessDecision(key,before,after){if(!after)return null;const goalKey=mission.goal==='connect'?'earth':'light',goalName=goalKey==='earth'?'Tierra visible':'luz solar';let kind='neutral',title='Probemos esa idea.',reason='Compará el resultado con otras configuraciones antes de decidir.';
 if(key==='goal'){kind='positive';title='¡Ya tenemos un objetivo!';reason=mission.goal==='connect'?'Priorizaste comunicar: miraremos las horas de Tierra visible. Aun así, el rover necesita energía y un enlace de radio válido.':'Priorizaste explorar con energía solar: miraremos las horas de luz y el balance del panel y la batería. También importan las comunicaciones.';}
 else if(key==='site'){const best=Math.max(...sites.map((_,i)=>missionAnalysis(i)[goalKey]));kind=after[goalKey]===best?'positive':'caution';title=kind==='positive'?'Buena opción para tu prioridad.':'Hay otra opción con más oportunidades.';reason=`Este sitio ofrece ${after[goalKey]} h de ${goalName}; la mejor cifra de estas ubicaciones es ${best} h para la misma fecha, margen y radio. ${kind==='positive'?'Cumple mejor ese criterio, aunque no certifica un alunizaje seguro.':'Podés mantenerlo por otro motivo, o cambiar de lugar para mejorar ese criterio.'}`;}
 else if(key==='date'){const delta=after[goalKey]-(before?.[goalKey]??after[goalKey]);kind=delta>0?'positive':delta<0?'caution':'neutral';title=delta>0?'La nueva fecha ayuda a tu objetivo.':delta<0?'Esta fecha reduce tus oportunidades.':'La fecha quedó aplicada.';reason=`La fecha elegida tiene ${after[goalKey]} h de ${goalName} en siete días${delta?`, ${Math.abs(delta)} h ${delta>0?'más':'menos'} que antes`:'. En este criterio no cambió la cantidad de horas'}. El cálculo usa el registro NASA de esa hora; también compará las otras condiciones.`;}
 else if(key==='capacity'||key==='tracking'){kind=after.budget.unservedWh<.01?'positive':'caution';title=kind==='positive'?'El balance cubre el consumo elegido.':'Esta configuración se queda sin energía.';reason=`Con ${mission.capacity} Wh y ${mission.tracking?'seguimiento solar ideal':'panel horizontal fijo'}, el modelo genera ${Math.round(after.budget.generatedWh)} Wh y deja ${Math.round(after.budget.unservedWh)} Wh de demanda sin cubrir. ${kind==='positive'?'Funciona en este balance simplificado; faltan temperatura y otras validaciones.':'Probá seguimiento, otra batería, otro sitio o fecha. Una batería almacena; no genera energía.'}`;}
 else if(key==='height'){const gain=(before?.outage??after.outage)-after.outage;kind=gain>0?'positive':'neutral';title=gain>0?'La altura reduce el corte.':'Más altura no siempre mejora la vista.';reason=`Con ${mission.height} m, el mayor corte es ${after.outage} h${gain>0?`, ${gain} h menos que antes`:'. No se redujo frente a tu elección anterior'}. El relieve puede seguir bloqueando la Tierra; también puede haber obstáculos fuera del radio analizado. La demo no evalúa el peso ni la viabilidad mecánica de esa altura.`;}
 else if(key==='store'){const bad=(!mission.store&&after.outage>0)||(mission.store&&after.earth===0);kind=bad?'caution':'positive';title=bad?'Tu estrategia necesita una solución más.':mission.store?'Podés aprovechar las próximas ventanas.':'La geometría no muestra cortes en el período.';reason=mission.store?(after.earth===0?'Podés guardar los datos, pero no hay Tierra visible en estos siete días para enviarlos. Necesitás otra fecha, lugar o arquitectura.':`Guardar datos permite esperar las ${after.earth} h de Tierra visible. El mayor corte es ${after.outage} h; no tenés comunicación en tiempo real durante ese corte.`):`Pediste tiempo real. El mayor corte geométrico es ${after.outage} h. ${after.outage?'Esa configuración no cumple el contacto continuo que elegiste.':'Aun así, hay que verificar estación terrestre y radio.'}`;}
 guideClosed=false;return{kind,title,reason};}
function decisionFeedbackMarkup(){const f=missionFeedback;return f?`<section class="decision-response ${f.kind}" role="status"><span>${f.kind==='positive'?'✓':f.kind==='caution'?'△':'↔'} FÉLICETTE · DESPUÉS DE TU ELECCIÓN</span><h2>${f.title}</h2><p>${f.reason}</p><small>Evaluamos el objetivo y los supuestos del juego. Podés cambiar tu elección y volver a probar.</small></section>`:'';}
function applyDateValue(value){const before=missionAnalysis(),d=new Date(value+'Z'),idx=(d-Date.UTC(2025,0,1))/3600000;if(!Number.isFinite(idx)||idx<0||idx>lastPlanningIndex()||!Number.isInteger(idx)){if($('gameDateStatus'))$('gameDateStatus').textContent='Sin datos para esa fecha. Elegí entre 01/01/2025 y 24/12/2026, a una hora en punto.';return false;}mission.date=value;mission.previewHour=0;guideTipIndex=0;missionFeedback=assessDecision('date',before,missionAnalysis());renderMission();return true;}
function applyMissionDate(){const calendar=$('gameCalendar'),hour=$('gameHour');if(!calendar.value||!calendar.checkValidity()){$('gameDateStatus').textContent='La fecha todavía no es válida. Usá el calendario entre 01/01/2025 y 24/12/2026.';calendar.setAttribute('aria-invalid','true');return;}calendar.removeAttribute('aria-invalid');applyDateValue(calendar.value+'T'+hour.value+':00');}
